from __future__ import annotations

import sys
from pathlib import Path

import pytest

# the app has no package install: import it from its folder
APP_DIR = Path(__file__).resolve().parents[3] / "experimental" / "reflex-kernel"
sys.path.insert(0, str(APP_DIR))

from reflex_kernel import logs  # noqa: E402


@pytest.mark.parametrize(
    ("where", "target"),
    [
        # the most precise wins: a tool call over the turn it was part of
        ({"tool_call_id": "toolu_1", "turn": "turn-2"}, ("call-toolu_1", "↖ tool call")),
        ({"turn": "turn-2"}, ("turn-2", "↖ chat")),
        ({"slot": "tab:r3"}, ("tab:r3", "↖ r3")),
        ({"slot": "chat:r3"}, ("ref-r3", "↖ r3 in chat")),
        ({"slot": "cell:c2"}, ("cell:c2", "↖ cell")),
        ({}, ("", "")),
    ],
)
def test_where_a_record_links_to(where, target):
    assert logs._target(where) == target  # the mapping itself is what's tested


def test_a_graphql_row_has_its_link_curl_and_summary():
    record = {
        "id": 1,
        "time": 1_790_000_000.0,
        "kind": "graphql",
        "source": "startgg",
        "op": "PlayerSets",
        "variables": {"id": 1, "page": 3},
        "query": "query PlayerSets($id: ID!) { a }",
        "method": "POST",
        "url": "https://api.start.gg/gql/alpha",
        "request_headers": {"authorization": "Bearer [filtered]"},
        "status": 200,
        "ms": 412,
        "rows": 15,
        "objects": 495,
        "tool_call_id": "toolu_1",
        "session": "abc12345",
    }
    row = logs._row(record)
    assert row["summary"] == "PlayerSets page 3 · 200 · 412 ms · 15 rows · 495 objects"
    assert (row["target"], row["target_label"], row["session"]) == ("call-toolu_1", "↖ tool call", "abc12345")
    assert "$AUTHORIZATION" in row["curl"]
    assert '"variables":{"id":1,"page":3}' in row["curl"]


_TOOL = {"tool_call_id": "toolu_1", "turn": "turn-2"}
_FORM_IN_TAB = {"slot": "tab:r3"}
_FORM_IN_CHAT = {"slot": "chat:r3"}
_CELL = {"slot": "cell:c1"}
_OTHER = {"tool_call_id": "toolu_9", "turn": "turn-5"}


@pytest.mark.parametrize(
    ("focus", "made_by", "shown"),
    [
        ("call-toolu_1", "", [_TOOL]),
        ("turn-2", "", [_TOOL]),
        # a result: the call that made it, and form runs in its tab or unfolded in the chat
        ("tab:r3", "toolu_1", [_TOOL, _FORM_IN_TAB, _FORM_IN_CHAT]),
        ("tab:r3", "", [_FORM_IN_TAB, _FORM_IN_CHAT]),  # added by hand: no call made it
        ("cell:c1", "", [_CELL]),
        ("", "", [_TOOL, _FORM_IN_TAB, _FORM_IN_CHAT, _CELL, _OTHER]),
    ],
)
def test_in_focus_is_the_reverse_of_the_links(focus, made_by, shown):
    records = [_TOOL, _FORM_IN_TAB, _FORM_IN_CHAT, _CELL, _OTHER]
    assert [r for r in records if logs.in_focus(r, focus, made_by)] == shown


def test_rows_of_one_session_leave_out_the_others(monkeypatch):
    """What a fresh window's debug log shows (State.debug_mine is on by default): its own
    records, not earlier windows' or those made outside any browser tab.
    """
    records = [
        {"id": 1, "time": 1_790_000_000.0, "kind": "tool", "session": "earlier1"},
        {"id": 2, "time": 1_790_000_001.0, "kind": "tool"},
        {"id": 3, "time": 1_790_000_002.0, "kind": "tool", "session": "mine0000"},
    ]
    monkeypatch.setattr(logs, "_records", records)
    assert logs.rows([], session="fresh000") == ([], 0)
    mine, count = logs.rows([], session="mine0000")
    assert (count, [row["session"] for row in mine]) == (1, ["mine0000"])
    assert logs.rows([])[1] == 3  # unticked: every session's
